/** Generated by `gameengine playable build` from the ad's playable.json and exported assets. */
declare module 'playable:manifest' {
  /** Core image data URLs by the key in playable.json `assets` (assets in a phase arrive through `createPhaseLoader`). */
  export const images: Record<string, string>;
  /** Audio data URLs by key. */
  export const sounds: Record<string, string>;
  /** Video data URLs by key (.mp4, .webm): `createAlphaVideo` from @gameengine/playable plays them, stacked alpha by default. */
  export const videos: Record<string, string>;
  /** Packed base64 by key (`fileBytes` from @gameengine/playable unpacks): `.glb` meshes and `.mat.json` materials for `createRenderer3D`. */
  export const files: Record<string, string>;
  /** playable.json `phases` as built, in priority order: give them to `createPhaseLoader` from @gameengine/playable. */
  export const phases: {
    name: string;
    start: 'load' | 'first-touch';
    deadlineSec: number;
    bytes: number;
    transport: 'inline' | 'package' | 'remote';
    src: string;
  }[];
  export const ad: { name: string; title: string; cta: string; storeUrl: { ios: string; android: string } };
  export const aliases: Record<string, string>;
}

declare module 'playable:slice' {
  export const scene: string;
  export const seed: number;
  export const dt: number;
  export const sortingLayers: string[];
  export const pixelsPerUnit: number;
  export const clips: Record<string, string>;
  /** `*.timeline.json` files the slice names, base64, by asset key: give them to `new Timelines(…)` for createPlayable. */
  export const timelines: Record<string, string>;
  /** `*.vfx.json` / compiled `*.vfx.ts` effects the slice names, base64, by asset key. */
  export const effects: Record<string, string>;
  export const skeletons: Record<string, string>;
  export const skel2dWasm: string;
  /** The 3D physics module (engine bridge + lite Jolt), packed and base64 (`Physics3dWasm.fromBytes` unpacks it); empty unless the slice names RigidBody3D or Collider3D. */
  export const physics3dWasm: string;
  /** playable.json `data`: data records by key, for `loadData`. */
  export const data: Record<string, unknown>;
  /** playable.json `colliderMeshes`: cooked hull geometry (`LMSH`) by key, base64. */
  export const meshes: Record<string, string>;
}
